"use client";

import {
  type InputHTMLAttributes,
  type KeyboardEvent,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { cx } from "../utils/cx";
import { Tag } from "./tag";
import { CheckIcon, ChevronDownIcon } from "../icons/interface";

export type ComboboxOption = {
  value: string;
  label: string;
  /** Secondary text, matched by the filter. */
  description?: string;
  disabled?: boolean;
};

type Shared = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "value" | "defaultValue" | "onChange" | "type" | "role" | "size" | "multiple"
> & {
  options: ComboboxOption[];
  placeholder?: string;
  emptyMessage?: string;
  disabled?: boolean;
  /** Replace the default filter (a case-insensitive match on label and description). */
  filter?: (option: ComboboxOption, query: string) => boolean;
};
export type ComboboxProps = Shared &
  (
    | { multiple?: false; value?: string; defaultValue?: string; onValueChange?: (value: string) => void }
    | { multiple: true; value?: string[]; defaultValue?: string[]; onValueChange?: (value: string[]) => void }
  );

const defaultFilter = (o: ComboboxOption, q: string) =>
  `${o.label} ${o.description ?? ""}`.toLowerCase().includes(q.toLowerCase());

/**
 * A text field with a filtered list of options (ARIA combobox: focus stays in the input, Up/Down move the highlight
 * with `aria-activedescendant`, Enter picks, Escape closes). Single choice shows the label in the field; `multiple`
 * shows each choice as a removable tag and Backspace removes the last. Use `Select` for a short list without search.
 */
export function Combobox(props: ComboboxProps) {
  const {
    options,
    multiple,
    placeholder,
    emptyMessage = "No matches.",
    disabled,
    filter = defaultFilter,
    className,
    id,
    onBlur,
    onKeyDown,
    ...inputRest
  } = props;
  const {
    value: _value,
    defaultValue: _dv,
    onValueChange: _ovc,
    ...input
  } = inputRest as Record<string, unknown> as Record<string, unknown> & InputHTMLAttributes<HTMLInputElement>;
  const auto = useId();
  const listId = `${auto}-list`;
  const initial = (props as { defaultValue?: string | string[] }).defaultValue;
  const [inner, setInner] = useState<string[]>(
    initial === undefined ? [] : Array.isArray(initial) ? initial : initial ? [initial] : [],
  );
  const controlled = (props as { value?: string | string[] }).value;
  const selected =
    controlled === undefined ? inner : Array.isArray(controlled) ? controlled : controlled ? [controlled] : [];
  const onValueChange = (props as { onValueChange?: (v: never) => void }).onValueChange;

  const labelOf = useCallback((v: string) => options.find((o) => o.value === v)?.label ?? v, [options]);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [typed, setTyped] = useState(false);
  const [active, setActive] = useState(0);
  const root = useRef<HTMLDivElement>(null);
  const field = useRef<HTMLInputElement>(null);
  const list = useRef<HTMLDivElement>(null);

  const shown = useMemo(() => {
    const q = typed ? query.trim() : "";
    const pool = q ? options.filter((o) => filter(o, q)) : options;
    return pool;
  }, [options, query, typed, filter]);

  const commit = (next: string[]) => {
    if (controlled === undefined) setInner(next);
    onValueChange?.((multiple ? next : (next[0] ?? "")) as never);
  };
  const pick = (o: ComboboxOption | undefined) => {
    if (!o || o.disabled) return;
    if (multiple) {
      commit(selected.includes(o.value) ? selected.filter((v) => v !== o.value) : [...selected, o.value]);
      setQuery("");
      setTyped(false);
      field.current?.focus();
    } else {
      commit([o.value]);
      setQuery("");
      setTyped(false);
      setOpen(false);
    }
  };

  const { present, state } = usePresence(open, 160);
  useFloating(present, root, list, { side: "bottom", align: "start", offset: 6 });
  const close = useCallback(() => {
    setOpen(false);
    setTyped(false);
    setQuery("");
  }, []);
  useDismiss(open, root, list, close);
  // scroll the highlighted option into view
  // biome-ignore lint/correctness/useExhaustiveDependencies: runs when the highlight or the list changes
  useEffect(() => {
    list.current?.querySelector('[aria-selected="true"][data-active]')?.scrollIntoView?.({ block: "nearest" });
  }, [active, shown]);

  const move = (dir: 1 | -1) => {
    if (!shown.length) return;
    let i = active;
    for (let n = 0; n < shown.length; n++) {
      i = (i + dir + shown.length) % shown.length;
      if (!shown[i]?.disabled) break;
    }
    setActive(i);
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    (onKeyDown as ((e: KeyboardEvent<HTMLInputElement>) => void) | undefined)?.(e);
    if (e.defaultPrevented || disabled) return;
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!open) setOpen(true);
      else move(e.key === "ArrowDown" ? 1 : -1);
    } else if (e.key === "Enter" && open) {
      e.preventDefault();
      pick(shown[active]);
    } else if (e.key === "Escape" && open) {
      e.preventDefault();
      close();
    } else if (e.key === "Home" && open) {
      e.preventDefault();
      setActive(0);
    } else if (e.key === "End" && open) {
      e.preventDefault();
      setActive(Math.max(0, shown.length - 1));
    } else if (e.key === "Backspace" && multiple && !query && selected.length) {
      commit(selected.slice(0, -1));
    }
  };

  const display = multiple ? query : typed ? query : selected[0] ? labelOf(selected[0]) : "";
  const optionId = (i: number) => `${auto}-opt-${i}`;
  return (
    <div
      ref={root}
      className={cx("hm-combobox", className)}
      data-multiple={multiple ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
    >
      {/* biome-ignore lint/a11y/useKeyWithClickEvents: the input inside handles the keyboard; this click focuses it */}
      <div className="hm-combobox-field hm-control" onClick={() => field.current?.focus()}>
        {multiple
          ? selected.map((v) => (
              <Tag
                key={v}
                onRemove={(e) => {
                  e.stopPropagation();
                  commit(selected.filter((x) => x !== v));
                  field.current?.focus();
                }}
              >
                {labelOf(v)}
              </Tag>
            ))
          : null}
        <input
          {...(input as InputHTMLAttributes<HTMLInputElement>)}
          ref={field}
          id={id}
          type="text"
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={open && shown.length ? optionId(active) : undefined}
          autoComplete="off"
          spellCheck={false}
          disabled={disabled}
          placeholder={multiple && selected.length ? undefined : placeholder}
          value={display}
          className="hm-combobox-input"
          onFocus={() => !disabled && setOpen(true)}
          onClick={() => !disabled && setOpen(true)}
          onChange={(e) => {
            setQuery(e.target.value);
            setTyped(true);
            setActive(0);
            setOpen(true);
          }}
          onBlur={(e) => {
            onBlur?.(e);
            // clicking an option blurs the field first; the list handles its own pointer-down
            if (!list.current?.contains(e.relatedTarget as Node)) close();
          }}
          onKeyDown={key}
        />
        <ChevronDownIcon className="hm-combobox-chevron" size={14} />
      </div>
      {present ? (
        <div
          ref={list}
          id={listId}
          popover="manual"
          role="listbox"
          // focus stays in the input (options are announced through aria-activedescendant); without this a scrolling
          // list would become a Tab stop of its own
          tabIndex={-1}
          aria-multiselectable={multiple || undefined}
          data-state={state}
          inert={state === "closed" || undefined}
          className="hm-floating hm-menu hm-combobox-list"
          onPointerDown={(e) => e.preventDefault()}
        >
          {shown.length ? (
            shown.map((o, i) => (
              // biome-ignore lint/a11y/useKeyWithClickEvents: keyboard is handled by the combobox input
              <div
                key={o.value}
                id={optionId(i)}
                role="option"
                aria-selected={selected.includes(o.value)}
                aria-disabled={o.disabled || undefined}
                data-active={i === active ? "" : undefined}
                className="hm-combobox-option"
                onClick={() => pick(o)}
                onPointerMove={() => i !== active && !o.disabled && setActive(i)}
              >
                <span className="hm-combobox-label">{o.label}</span>
                {o.description ? <small className="hm-combobox-description">{o.description}</small> : null}
                <CheckIcon className="hm-combobox-check" size={12} strokeWidth={2} />
              </div>
            ))
          ) : (
            <p className="hm-combobox-empty" role="status">
              {emptyMessage}
            </p>
          )}
        </div>
      ) : null}
    </div>
  );
}
